export const NPC_CARD_COUNT = NPC_CARD_CATALOG.length;
export function npcCardByKey(key){ return NPC_CARD_CATALOG.find(v=>v.key===key) ?? null; }
export function npcCardsByKind(kind){ return NPC_CARD_CATALOG.filter(v=>v.kind===kind); }
export function searchNpcCards(query){ const q=String(query??'').trim().toLocaleLowerCase(); if(!q)return NPC_CARD_CATALOG.slice(); return NPC_CARD_CATALOG.filter(v=>[v.name,v.sourceCard,v.gearText,v.abilitiesText,...(v.weapons??[]).map(w=>w.name)].filter(Boolean).join(' \n').toLocaleLowerCase().includes(q)); }
